from fractions import Fraction
from math import nextafter,inf
from more_itertools import numeric_range
import subprocess
ns={'__name__':'more_itertools.old','__package__':'more_itertools'};exec(subprocess.check_output(['git','show','89f458445016dd3bcb242b423f48d5fca98afdcf:more_itertools/more.py']),ns)
