 for precision in (3,28):
  for traps in ('default','inexact','all'):
   results=[]
   for cls in (old,numeric_range):
    with localcontext() as c:
     c.prec=precision
     if traps=='inexact':c.traps[Inexact]=True
     if traps=='all':
      for signal in c.traps:c.traps[signal]=True
     r=cls(*args);c.clear_flags()
     try:v=(value in r,r.index(value))
     except Exception as exc:v=type(exc).__name__
     results.append((v,tuple(s.__name__ for s,f in c.flags.items() if f)))
   assert results[0]==results[1],(name,precision,traps,results)
print('12 Decimal baseline comparisons passed')
for args in [(Fraction(1,10),2.,Fraction(1,5)),(Fraction(1,2),2.,Fraction(1,4)),(Fraction(2),0.,Fraction(-1,4)),(0,5,1),(5,0,-1),(Fraction(0),5,Fraction(1)),(0,Fraction(5),Fraction(1,2))]:
 r=numeric_range(*args);items=list(r)
 queries=[0.,.1,.2,.25,.3,.5,1.,1.1,1.25,1.5,2.,3.,4.,5.]
 for value in queries:
  assert (value in r)==(value in items),(args,value,items)
  try:expected=items.index(value)
  except ValueError:
   try:r.index(value)
   except ValueError:pass
   else:raise AssertionError((args,value,'accepted nonmember'))
  else:assert r.index(value)==expected,(args,value)
print('98 exact-generator/float-query comparisons passed')
f=1e308;boundary=(int(f)+int(nextafter(f,-inf)))//2;expected=boundary if float(boundary)==f else boundary+1
for start,stop,step in [(-f,f,1.),(f,-f,-1.)]:
 r=numeric_range(start,stop,step);i=r.index(0.)
 assert i==expected and 0. in r
print('Extreme first occurrence preserved in both directions')
PY

