import ast, subprocess, decimal, itertools
from decimal import Decimal, localcontext
from fractions import Fraction
import more_itertools.more as m
src=subprocess.check_output(['git','show','a0995c75f3536588993d1d4ef8bbbc8927bb622f:more_itertools/more.py'],text=True)
node=next(n for n in ast.parse(src).body if isinstance(n,ast.ClassDef) and n.name=='numeric_range')
ns=dict(m.__dict__); exec('\n'.join(src.splitlines()[node.lineno-1:node.end_lineno]),ns); old=ns['numeric_range']; new=m.numeric_range
constructors=[int,float,Decimal,Fraction]
miss=[]; checks=0
for strict,prec in itertools.product([False,True],[2,28]):
 for types in itertools.product(constructors,repeat=3):
  for raw in [(0,5,1),(1,7,2),(5,0,-1),(0,5,2)]:
   args=tuple(t(v) for t,v in zip(types,raw))
   for querytype in constructors:
    for x in [0,1,2,3,4,5,6,7]:
     value=querytype(x)
     for op in ['contains','index','len']:
      res=[]
      for cls in (old,new):
       with localcontext() as ctx:
        ctx.prec=prec
        if strict:
         for signal in ctx.traps: ctx.traps[signal]=True
        ctx.clear_flags()
        try:
         r=cls(*args)
         val= value in r if op=='contains' else r.index(value) if op=='index' else len(r)
         outcome=('ok',val)
        except Exception as e: outcome=('error',type(e).__name__)
        res.append((outcome,tuple(k.__name__ for k,v in ctx.flags.items() if v)))
      checks+=1
      if res[0][0][0]=='ok' and res[0]!=res[1]:
       miss.append((strict,prec,tuple(t.__name__ for t in types),raw,querytype.__name__,x,op,res))
print('checks',checks,'baseline-legal deltas',len(miss))
for x in miss[:20]: print(x)
